cd /workspace && timeout 5 python -u -c "
from boltons.jsonutils import JSONLIterator
import io, sys
data = '{\"a\": 1}\n{\"b\": 2}\n{\"c\": 3}'
print('len', len(data))
for rs in (0.5, -0.5):
    fo = io.StringIO(data)
    print('rel_seek', rs)
    try:
        it = JSONLIterator(fo, rel_seek=rs)
    except Exception as e:
        print('  init err', repr(e)); continue
    for i in range(6):
        try:
            print('  ', next(it))
        except StopIteration:
            print('   StopIteration')
            break
" ; echo "exit=$?"

